// Original CC0 fixture. Simulates the archive envelope read by BooksParser;
// it is not an export generated by Apple Books itself.
import Foundation
import AppKit
import PDFKit
import PencilKit

final class DemoArchive: NSObject, NSCoding {
    let data: Data
    init(_ drawing: PKDrawing) { data = drawing.dataRepresentation() }
    required init?(coder: NSCoder) { fatalError("Encoding-only fixture") }
    func encode(with coder: NSCoder) {
        coder.encode(data as NSData, forKey: "drawing")
        coder.encode(["Width": 612.0, "Height": 792.0] as NSDictionary, forKey: "drawingSize")
    }
}

let root = URL(fileURLWithPath: CommandLine.arguments[1])
let doc = PDFDocument(url: root.appendingPathComponent("clean.pdf"))!
var archives: [String:String] = [:]
typealias Path = [CGPoint]
func p(_ values: [Double]) -> Path {
    stride(from:0,to:values.count,by:2).map{CGPoint(x:values[$0],y:values[$0+1])}
}
// Coordinates below use PDF's bottom-left origin. PKDrawing uses top-left.
func ink(_ page: PDFPage, paths: [Path], color: NSColor) throws {
    let strokes = paths.enumerated().map { idx, points -> PKStroke in
        let controls = points.enumerated().map { i, q in
            PKStrokePoint(location: CGPoint(x:q.x,y:792-q.y), timeOffset: Double(i)*0.02,
                          size:CGSize(width:3,height:3),opacity:1,force:0.5,azimuth:0,altitude:.pi/2)
        }
        return PKStroke(ink:PKInk(.pen,color:color),path:PKStrokePath(controlPoints:controls,creationDate:Date(timeIntervalSince1970:Double(idx))))
    }
    let drawing = PKDrawing(strokes:strokes)
    let archive = try NSKeyedArchiver.archivedData(withRootObject:DemoArchive(drawing),requiringSecureCoding:false)
    let a = PDFAnnotation(bounds:CGRect(x:0,y:0,width:612,height:792),forType:.ink,withProperties:nil)
    a.color=color;let border=PDFBorder();border.lineWidth=1.8;a.border=border
    for points in paths {
        let path=NSBezierPath();path.move(to:points[0]);for q in points.dropFirst(){path.line(to:q)};a.add(path)
    }
    // PDFKit rewrites its own extras during save; install our fixture after saving.
    archives[String(doc.index(for:page))] = archive.base64EncodedString()
    page.addAnnotation(a)
}
func highlight(_ page:PDFPage,_ text:String,_ comment:String) {
    guard let selection=page.document?.findString(text,fromSelection:nil,withOptions:[]) else {fatalError("Missing demo text")}
    let b=selection.bounds(for:page)
    let a=PDFAnnotation(bounds:b,forType:.highlight,withProperties:nil)
    a.color=NSColor(calibratedRed:1,green:0.83,blue:0.12,alpha:1);a.contents=comment
    page.addAnnotation(a)
}
let blue=NSColor(calibratedRed:0.12,green:0.34,blue:0.73,alpha:1)
let green=NSColor(calibratedRed:0.08,green:0.55,blue:0.40,alpha:1)
let page=doc.page(at:0)!
highlight(page,"Modulo keeps the remainder after division.","Keep the remainder, not the quotient.")
try ink(page,paths:[
    p([218,416,234,407,319,406,352,414,361,434,349,450,299,458,234,453,218,439,218,416]),
    p([280,407,275,377,250,360]),p([250,360,252,374]),p([250,360,264,362]),
    // A handwritten 2 in the exercise space.
    p([135,263,142,271,154,269,158,261,154,253,137,237,159,237]),
    p([128,228,167,229])
],color:blue)
let note=PDFAnnotation(bounds:CGRect(x:526,y:555,width:20,height:20),forType:.text,withProperties:nil)
note.contents="Demo note: try importing pages 1-2, then inspect each native Zotero annotation."
note.color = .systemOrange;page.addAnnotation(note)
let page2=doc.page(at:1)!
highlight(page2,"A larger empty gap can separate two independent notes.","White space controls grouping.")
try ink(page2,paths:[
    p([75,442,84,463,93,442]),p([79,451,89,451]),
    p([103,444,112,454,124,444]),p([128,445,140,459,153,444]),
    p([359,440,359,465,374,465,380,458,373,453,359,453,375,453,383,446,377,440,359,440]),
    p([396,447,408,457,421,447]),p([431,446,442,461,454,446])
],color:green)
guard doc.write(to:root.appendingPathComponent("annotated.pdf")) else {fatalError("PDF write failed")}
try JSONSerialization.data(withJSONObject:archives,options:[.sortedKeys]).write(to:root.appendingPathComponent("archives.json"))
print("Created annotated.pdf: synthetic PencilKit archive + PDF highlights + text note")
